const productos = $input.first().json.data || []
const nombres = [...new Set(productos.map(p => String(p.nombre).trim()))].sort((a, b) => a.localeCompare(b, 'es'))

const PLANILLAS = [
  { local: 'Fábrica',   documentId: 'PEGAR_ID_PLANILLA_FABRICA' },
  { local: 'Fisherton', documentId: 'PEGAR_ID_PLANILLA_FISHERTON' },
  { local: 'Norte',     documentId: 'PEGAR_ID_PLANILLA_NORTE' },
]

return PLANILLAS.map(p => ({ json: { ...p, nombres } }))

const ctx = $('Una salida por planilla').item.json
const hojas = ($input.item.json.sheets || []).map(s => s.properties)

const principal = hojas.find(h => h.title !== 'Catálogo')
const catalogo = hojas.find(h => h.title === 'Catálogo')
if (!principal) throw new Error(`${ctx.local}: no encontré la hoja principal`)

// Si la hoja Catálogo no existe la creamos con un id elegido por nosotros,
// así lo podemos usar en el mismo lote sin esperar la respuesta del addSheet.
const ID_CATALOGO = 987654
const sheetIdCatalogo = catalogo ? catalogo.sheetId : ID_CATALOGO
const hoja = principal.sheetId

const requests = []
if (!catalogo) {
  requests.push({ addSheet: { properties: { sheetId: ID_CATALOGO, title: 'Catálogo', hidden: true, gridProperties: { rowCount: 1000, columnCount: 1 } } } })
}

// Limpiar la columna antes de reescribirla: si un producto se dio de baja,
// no puede quedar colgado en el desplegable.
requests.push({
  updateCells: {
    range: { sheetId: sheetIdCatalogo, startRowIndex: 0, startColumnIndex: 0, endColumnIndex: 1 },
    fields: 'userEnteredValue',
  },
})

const filas = [{ values: [{ userEnteredValue: { stringValue: 'PRODUCTOS (se actualiza solo)' } }] }]
for (const n of ctx.nombres) filas.push({ values: [{ userEnteredValue: { stringValue: n } }] })
requests.push({
  updateCells: {
    start: { sheetId: sheetIdCatalogo, rowIndex: 0, columnIndex: 0 },
    rows: filas,
    fields: 'userEnteredValue',
  },
})

// Columnas: Fecha=0, Tipo=1, Producto=2, Talle=3, Color=4, Cantidad=5, ...
const col = (i, j) => ({ sheetId: hoja, startRowIndex: 1, startColumnIndex: i, endColumnIndex: j ?? i + 1 })

// Fecha: calendario al hacer doble click, y formato fijo para que los tres
// locales la escriban igual.
requests.push({
  setDataValidation: {
    range: col(0),
    rule: {
      condition: { type: 'DATE_IS_VALID' },
      showCustomUi: true,
      strict: false,
      inputMessage: 'Doble click para elegir la fecha en el calendario',
    },
  },
})
requests.push({
  repeatCell: {
    range: col(0),
    cell: { userEnteredFormat: { numberFormat: { type: 'DATE_TIME', pattern: 'dd/MM/yyyy HH:mm' } } },
    fields: 'userEnteredFormat.numberFormat',
  },
})

requests.push({
  setDataValidation: {
    range: col(2),
    rule: {
      condition: { type: 'ONE_OF_RANGE', values: [{ userEnteredValue: "='Catálogo'!$A$2:$A$1000" }] },
      showCustomUi: true,
      strict: true,
      inputMessage: 'Elegí el producto de la lista',
    },
  },
})

requests.push({
  setDataValidation: {
    range: col(1),
    rule: {
      condition: { type: 'ONE_OF_LIST', values: [{ userEnteredValue: 'VENTA' }, { userEnteredValue: 'INGRESO' }, { userEnteredValue: 'AJUSTE' }] },
      showCustomUi: true,
      strict: true,
    },
  },
})

return { json: { local: ctx.local, documentId: ctx.documentId, cantidad: ctx.nombres.length, body: { requests } } }
